{
  "гриб": "Amanita muscaria (красный мухомор)",
  "состав": [
    {
      "вещество": "Муцимол (muscimol)",
      "содержание": "0,05–0,25 % от свежего веса (0,5–2,5 % от сухого веса)",
      "влияние": "Агонист ГАМК-A рецепторов; основной психоактивный компонент, вызывает седацию, миоклонус и гипноз."
    },
    {
      "вещество": "Иботеновая кислота (ibotenic acid)",
      "содержание": "0,04–0,15 % от свежего веса (0,4–1,5 % от сухого веса)",
      "влияние": "Агонист глутаматных (NMDA) рецепторов; нейротоксин, вызывает возбуждение, тремор и судороги."
    },
    {
      "вещество": "Аманитидин (amanitadin)",
      "содержание": "≈ 0,5 % от сухого веса",
      "влияние": "Циклический амин с умеренной ингибиторной активностью к холинэстеразе, усиливает холинергический ответ ЦНС."
    },
    {
      "вещество": "Аманитулин (amanituline)",
      "содержание": "< 0,1 % от сухого веса (следовое)",
      "влияние": "Биогенный амин, вклад в общую токсичность и психоактивность незначителен."
    },
    {
      "вещество": "Мусказон (muscazone, 3-гидрокси-муцимол)",
      "содержание": "< 0,01 % от сухого веса (следовое)",
      "влияние": "Гидроксигруппа в положении 3 повышает сродство к ГАМК-A рецептору, усиливая седативный эффект муцимола."
    },
    {
      "вещество": "Мусцин (muscine)",
      "содержание": "следовое (< 0,01 % от сухого веса)",
      "влияние": "Амид иботеновой кислоты, обладает слабой нейротропной активностью."
    },
    {
      "вещество": "Красные пигменты шляпки (смесь, вкл. эритроспорейн и др.)",
      "содержание": "неизвестно",
      "влияние": "Комплекс пигментов, придающий шляпке характерную красную окраску; фотозащитная и структурная функция в ткани гимениофора."
    },
    {
      "вещество": "Маннит (mannitol)",
      "содержание": "5–10 % от сухого веса",
      "влияние": "Основной осмотически-активный сахар гриба, обеспечивает тургор и является источником энергии."
    },
    {
      "вещество": "Эргостерол (ergosterol)",
      "содержание": "неизвестно",
      "влияние": "Основной стерол мембран гриба, провитамин D₂; при переваривании может частично усваиваться человеком."
    }
  ]
}

{
  "гриб": "Amanita pantherina (пантерный мухомор)",
  "состав": [
    {
      "вещество": "мусцимол",
      "содержание": "≈ 3–10 мг/г сухого веса (до ~1 % сухого веса)",
      "влияние": "Агонист ГАМК-А рецепторов, вызывает седацию, судороги и галлюцинации."
    },
    {
      "вещество": "иботеновая кислота",
      "содержание": "≈ 1–5 мг/г сухого веса (0,1–0,5 % сухого веса)",
      "влияние": "Агонист NMDA-рецепторов, вызывает возбуждение ЦНС, судороги и потенциальное повреждение нейронов."
    },
    {
      "вещество": "мускарин",
      "содержание": "≈ 0,005–0,02 % от свежего веса",
      "влияние": "Агонист мускариновых холинергических рецепторов, вызывает слюнотечение, потливость, брадикардию и бронхоспазм."
    },
    {
      "вещество": "пантерин",
      "содержание": "неизвестно (следовые количества, точные цифры не стандартизированы)",
      "влияние": "Предполагаемый алкалоид, усиливающий судорожный и галлюциногенный профиль отравления, характерный именно для A. pantherina."
    },
    {
      "вещество": "ГАМК (γ-аминомасляная кислота)",
      "содержание": "следовые количества (менее 0,1 % сухого веса)",
      "влияние": "Основной тормозной нейромедиатор; в высоких дозах усиливает депррессивный эффект мусцимола на ЦНС."
    }
  ]
}

{
  "гриб": "Amanita citrina (лимонный мухомор, поганковидный)",
  "состав": [
    {
      "вещество": "α-Аманитин (альфа-аманитин)",
      "содержание": "0,1–0,2 % от сухого веса (макс. до 0,5 %)",
      "влияние": "Сильно ингибирует РНК-полимеразу II, вызывая клеточную гибель гепатоцитов и почечных клеток."
    },
    {
      "вещество": "β-Аманитин (бета-аманитин)",
      "содержание": "0,05–0,1 % от сухого веса",
      "влияние": "Ингибирует РНК-полимеразу II с меньшей аффинностью, чем α-аманитин, усиливая печёночный и почечный токсикоз."
    },
    {
      "вещество": "γ-Аманитин (гамма-аманитин)",
      "содержание": "< 0,01 % от сухого веса (следы)",
      "влияние": "Слабый ингибитор РНК-полимеразы II; вносит небольшой вклад в суммарную аматотоксичность."
    },
    {
      "вещество": "ε-Аманитин (эпсилон-аманитин)",
      "содержание": "неизвестно (следы)",
      "влияние": "Слабый ингибитор РНК-полимеразы II; обнаружен в малых количествах."
    },
    {
      "вещество": "4-Аминокротовая кислота (фаллацидин)",
      "содержание": "неизвестно (часть летучей фракции фаллацидинов)",
      "влияние": "Летучий нейротоксин, способствующий центрально-нервным и желудочно-кишечным симптомам отравления."
    },
    {
      "вещество": "2-Метил-3-бутен-2,3-диол (метиловый бутинолид)",
      "содержание": "неизвестно (часть фаллацидинов)",
      "влияние": "Летучий токсин, разрушается при сушке; усиливает нейротоксический эффект."
    },
    {
      "вещество": "Метилдигидромиростецин (MDHM)",
      "содержание": "неизвестно (часть фаллацидинов)",
      "влияние": "Летучий алкалоидоподобный токсин с умеренным нейротропным действием."
    },
    {
      "вещество": "Цитровиллеин (жёлтый бетаиновый пигмент)",
      "содержание": "неизвестно (обуславливает жёлто-зелёную окраску шляпки)",
      "влияние": "Водорастворимый пигмент (беталаин), придающий характерную жёлтую окраску; сам по себе не токсичен."
    },
    {
      "вещество": "Бетанидин (беталаиновый прекурсор)",
      "содержание": "неизвестно (следы в шляпке)",
      "влияние": "Водорастворимый пигмент; метаболитически связан с синтезом цитровиллеина."
    },
    {
      "вещество": "Эрготионеин",
      "содержание": "~0,5–1 % от сухого веса (типично для базидиомицетов)",
      "влияние": "Антиоксидантный аминокислотный аналог; защищает клетки от оксидативного стресса."
    },
    {
      "вещество": "Манинит",
      "содержание": "~2–5 % от сухого веса",
      "влияние": "Сахарный спирт, структурный и метаболический компонент гиф; нейтрален для человека."
    },
    {
      "вещество": "Тrehalose (трегалоза)",
      "содержание": "~3–6 % от сухого веса",
      "влияние": "Дисахарид, запасной полисахарид; нейтрален, но участвует в осморегуляции клеток гриба."
    },
    {
      "вещество": "Инозитол (мезо-инозитол)",
      "содержание": "неизвестно (типично 1–3 % от сухого веса для Amanita)",
      "влияние": "Циклический полиол, компонент фосфолипидов; сам по себе не токсичен."
    }
  ]
}
